<template>
    <div class="login">

        <br>
        <div class="usernamecontainer">
            <span>用户名： </span>
            <el-select v-model="username" filterable placeholder="请选择" class="select-input">
                <el-option v-for="item in usernameOptions" :key="item.value" :label="item.label" :value="item.value">
                </el-option>
            </el-select>
        </div>
        <br>
        <div class="passwordcontainer">
            <span>&nbsp;&nbsp;&nbsp;&nbsp;密码： </span>
            <el-input placeholder="请输入密码" v-model="password" show-password class="password-input"></el-input>
        </div>
        <br>
        <div class="buttoncontainer">
            <span>&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span>
            <el-button type="primary" @click="login()" class="login-btn">登录</el-button>
        </div>
        <br>
    </div>
</template>
<style scoped>

  .login {
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      min-height: 100vh;
      /* 使.login元素至少和视口一样高 */
      background: rgb(234, 176, 69);
      box-sizing: border-box;
      /* 确保边距包含在宽度和高度内 */
      padding: 20px;
      /* 添加一些内边距 */
  }

  .select-input,
  .password-input {
      width: 300px !important;
      /* 设置用户名框和密码框的宽度一致 */
      margin-bottom: 20px;
      /* 添加下边距以分开输入框和按钮 */
  }

  .login-btn {
      width: 300px !important;
      /* 设置登录按钮宽度与输入框一致 */
  }
</style>

<script>
import axios from 'axios'
import {resetrouter, addserveroutes} from '@/router/example5'
const options = {
data(){
    return {

        usernameOptions: [{
          value: 'yang',
          label: '杨瑜瑾'
        }, {
          value: 'yu',
          label: '于文字'
        }, {
          value: 'tang',
          label: '唐佳'
        }, {
          value: 'zhang',
          label: '张会'
        }, {
          value: 'huang',
          label: '黄景媚'
        }],
        username: '',

        //密码框
        password:'123'
    }
},
methods: {
    async login() {
        resetrouter(); // 重置路由
        try {
            const resp = await axios.get(`/tpi/login/menu/${this.username}`);
            const array = resp.data.data;
            // 将得到的array数据存储到会话中；
            sessionStorage.setItem('serveRoutes', JSON.stringify(array));
            addserveroutes(array);
            this.$router.push('/');
        } catch (error) {
            // 这里处理登录失败的情况
            this.$message.error('用户名或密码错误');
        }
    

        axios.get('api/login', { params: { username: this.username } })
            .then(response => {
                const token = response.data.data;
                localStorage.setItem('token', token);
                localStorage.setItem('username',this.username);
            })
            .catch(error => { // 注意这里使用箭头函数
                this.$message.error('登录失败：' + error.message); // 使用error.message获取错误信息
            });


        



    }
}}


export default options;

</script>